function validate([nums, k]) {
  if (!Array.isArray(nums) || nums.length < 1 || nums.length > 100000) return 'nums needs 1 to 10^5 values.';
  if (!Number.isInteger(k) || k < 1 || k > nums.length) return 'k is between 1 and the length of nums.';
  if (nums.some(v => !Number.isInteger(v) || v < 1 || v > 1000000000)) return 'Each value is a whole number from 1 to 10^9.';
  if (new Set(nums).size !== nums.length) return 'The values in nums must be distinct.';
  return null;
}

