function largestSubarray(nums, k) {
  const lastStart = nums.length - k;
  let start = 0;
  for (let i = 1; i <= lastStart; i++) {
    if (nums[i] > nums[start]) {
      start = i;
    }
  }
  return nums.slice(start, start + k);
}

