function largestSubarray(nums, k) {
  let best = null;
  for (let from = 0; from + k <= nums.length; from++) {
    const candidate = [];
    for (let j = from; j < from + k; j++) candidate.push(nums[j]);
    if (best === null) {
      best = candidate;
      continue;
    }
    let j = 0;
    while (j < k && candidate[j] === best[j]) j++;
    if (j < k && candidate[j] > best[j]) best = candidate;
  }
  return best;
}

