function generate(rand, size) {
  const n = size === 'large' ? 2000 : 1 + Math.floor(rand() * 8);
  const limit = size === 'large' ? 1000000000 : 20;
  const used = new Set();
  const nums = [];
  while (nums.length < n) {
    const value = 1 + Math.floor(rand() * limit);
    if (used.has(value)) continue;
    used.add(value);
    nums.push(value);
  }
  const k = 1 + Math.floor(rand() * n);
  return [nums, k];
}
